#!/bin/sh
set -eu

root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
generator=$(mktemp -d)
trap 'rm -rf "$generator"' EXIT HUP INT TERM

# Go's formatter and descriptor gzip output are part of the generated bytes.
GOWORK=off GOTOOLCHAIN=go1.27.0 GOBIN="$generator" \
  go install github.com/gogo/protobuf/protoc-gen-gogofaster@v1.3.2
protoc --plugin="protoc-gen-gogofaster=$generator/protoc-gen-gogofaster" \
  --proto_path="$root/types" --gogofaster_out="$root/types" "$root/types/netcap.proto"
